<?php require __DIR__.'/bootstrap.php';require_admin();$items=read_json('products.json',[]);$message='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');if($action==='delete'){$id=(string)($_POST['id']??'');$items=array_values(array_filter($items,fn($p)=>$p['id']!==$id));write_json('products.json',$items);$message='Product deleted. Historical orders remain unchanged.';}elseif($action==='save'){$id=trim((string)($_POST['id']??''));$name=trim((string)($_POST['name']??''));$category=trim((string)($_POST['category']??''));$description=trim((string)($_POST['description']??''));$image=trim((string)($_POST['image']??''));$price=max(0,(float)($_POST['price']??0));$sizes=[];$sizeLines=preg_split('/\r\n|\r|\n/',trim((string)($_POST['sizes']??'')));foreach($sizeLines as $line){$parts=explode('|',$line,2);if(count($parts)===2&&trim($parts[0])!=='')$sizes[]=['label'=>trim($parts[0]),'price'=>max(0,(float)$parts[1])];}$flavours=[];$flavourLines=preg_split('/\r\n|\r|\n/',trim((string)($_POST['flavours']??'')));foreach($flavourLines as $line){$parts=explode('|',$line,2);if(count($parts)===2&&trim($parts[0])!=='')$flavours[]=['label'=>trim($parts[0]),'extra'=>max(0,(float)$parts[1])];}
// --- IMAGE UPLOAD HANDLING (replaces Image URL) ---
if(isset($_FILES['image_file']) && is_array($_FILES['image_file']) && ($_FILES['image_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){
    if($_FILES['image_file']['error']!==UPLOAD_ERR_OK){$message='Image upload failed (error '.$_FILES['image_file']['error'].').';}
    else{
        $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];
        $finfo=finfo_open(FILEINFO_MIME_TYPE);
        $mime=finfo_file($finfo,$_FILES['image_file']['tmp_name']);
        finfo_close($finfo);
        if(!isset($allowed[$mime])){$message='Unsupported image type. Use JPG, PNG, WEBP or GIF.';}
        elseif($_FILES['image_file']['size']>5*1024*1024){$message='Image too large (max 5MB).';}
        else{
            $uploadDir=__DIR__.'/uploads';
            if(!is_dir($uploadDir))@mkdir($uploadDir,0755,true);
            $filename='product-'.bin2hex(random_bytes(6)).'.'.$allowed[$mime];
            if(move_uploaded_file($_FILES['image_file']['tmp_name'],$uploadDir.'/'.$filename)){
                $image='uploads/'.$filename;
            }else{$message='Could not save uploaded image.';}
        }
    }
}
// --- END IMAGE UPLOAD ---
if($name&&$description&&$image&&$price>0){$new=['id'=>$id?:'product-'.bin2hex(random_bytes(5)),'name'=>$name,'category'=>$category,'description'=>$description,'image'=>$image,'price'=>$price,'sizes'=>$sizes?:[['label'=>'Standard','price'=>$price]],'flavours'=>$flavours?:[['label'=>'Standard','extra'=>0]],'available'=>isset($_POST['available']),'featured'=>isset($_POST['featured'])];$found=false;foreach($items as &$p)if($p['id']===$new['id']){$p=$new;$found=true;break;}unset($p);if(!$found)$items[]=$new;write_json('products.json',$items);$message='Product saved.';}elseif($message==='')$message='Complete product name, description, image upload and a price greater than zero.';}}$edit=null;if(isset($_GET['edit']))foreach($items as $p)if($p['id']===$_GET['edit'])$edit=$p;site_header('Manage products'); ?>
