</style>
<div class="admin-shell"><div class="eyebrow">Owner workspace</div><h1 style="font:42px 'Playfair Display',serif">Product studio</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><?php if($message): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?><div class="cart-layout"><form class="card-panel" method="post" enctype="multipart/form-data"><h2><?= $edit?'Edit product':'Add a product' ?></h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="field"><label>Product name</label><input name="name" required value="<?= e($edit['name']??'') ?>"></div><div class="field"><label>Category <small>(optional)</small></label><input name="category" value="<?= e($edit['category']??'') ?>"></div><div class="field"><label>Description</label><textarea name="description" required><?= e($edit['description']??'') ?></textarea></div><div class="field"><label>Product image</label><input type="file" name="image_file" accept="image/jpeg,image/png,image/webp,image/gif"><small>JPG, PNG, WEBP or GIF — max 5MB. Images are cropped to a uniform square (1:1) in the catalogue.</small><?php if(!empty($edit['image'])): ?><div style="margin-top:8px"><img class="product-thumb" src="<?= e($edit['image']) ?>" alt="Current image"></div><?php endif; ?></div><div class="field"><label>Starting price (NGN)</label><input type="number" min="1" name="price" required value="<?= e($edit['price']??'') ?>"></div><div class="field"><label>Sizes (one per line: Label|price)</label><textarea name="sizes" placeholder="6 inch|28000&#10;8 inch|38000"><?php foreach(($edit['sizes']??[]) as $s)echo e($s['label'].'|'.$s['price'])."\n"; ?></textarea></div><div class="field"><label>Flavours (one per line: Label|extra charge)</label><textarea name="flavours" placeholder="Vanilla|0&#10;Chocolate|2500"><?php foreach(($edit['flavours']??[]) as $f)echo e($f['label'].'|'.$f['extra'])."\n"; ?></textarea></div><label><input type="checkbox" name="available" <?= !isset($edit)||!empty($edit['available'])?'checked':'' ?>> Available for purchase</label><br><label><input type="checkbox" name="featured" <?= !empty($edit['featured'])?'checked':'' ?>> Featured on homepage</label><p><button class="button" type="submit">Save product</button> <a class="button button-outline" href="admin-products.php">Clear</a></p></form><div class="card-panel"><h2>Catalogue</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Image</th><th>Product</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><img class="product-thumb" src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"></td><td><?= e($p['name']) ?><br><small><?= e($p['category']??'') ?></small></td><td><?= money((float)$p['price']) ?></td><td><?= !empty($p['available'])?'Available':'Unavailable' ?></td><td><a class="text-link" href="?edit=<?= urlencode($p['id']) ?>">Edit</a><form method="post" style="margin-top:8px"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($p['id']) ?>"><button class="text-link" data-confirm="Delete this product?" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php site_footer(); ?>